-- Current salary package of active staff, grouped by branch, job title and nationality, so the page can filter and still get exact min, max and average.
-- One text column LN = branch|job|nationality code|n|sum package|min package|max package|sum basic|min basic|max basic. Package = BASIC_SALARY + the allowance lines of the latest open default salary (same rule as hr02). About 115 rows.
SELECT (CASE WHEN x.ORG IN ('001','002','003','004') THEN '0'||SUBSTR(x.ORG,3,1) ELSE SUBSTR(NVL(x.ORG,'??'),1,2) END)||'|'||REPLACE(NVL(x.JOB,'?'),CHR(10),'')||'|'||NVL(TO_CHAR(x.NAT),'?')||'|'||COUNT(*)||'|'||ROUND(SUM(x.TOT))||'|'||ROUND(MIN(x.TOT))||'|'||ROUND(MAX(x.TOT))||'|'||ROUND(SUM(x.BAS))||'|'||ROUND(MIN(x.BAS))||'|'||ROUND(MAX(x.BAS)) LN FROM (SELECT c.STAFF_ID, m.NATIONALITY_CODE NAT, t.ORG, j.DESCRIPTION JOB, NVL((SELECT MAX(s.BASIC_SALARY) FROM {P}PR_STAFF_DEFAULT_SALARY_M s WHERE s.STAFF_ID=c.STAFF_ID AND s.DATE_END IS NULL),0) BAS, NVL((SELECT MAX(s.BASIC_SALARY) FROM {P}PR_STAFF_DEFAULT_SALARY_M s WHERE s.STAFF_ID=c.STAFF_ID AND s.DATE_END IS NULL),0) + NVL((SELECT SUM(d.SALARY_ITEM_AMOUNT) FROM {P}PR_STAFF_DEFAULT_SALARY_D d WHERE d.STAFF_ID=c.STAFF_ID AND d.DATE_START=(SELECT MAX(s2.DATE_START) FROM {P}PR_STAFF_DEFAULT_SALARY_M s2 WHERE s2.STAFF_ID=c.STAFF_ID AND s2.DATE_END IS NULL)),0) TOT FROM {P}PS_STAFF_CONTRACT c JOIN {P}STAFF_MASTER m ON m.STAFF_ID=c.STAFF_ID LEFT JOIN (SELECT STAFF_ID, MAX(ORGANIZATION_NO) ORG, MAX(STAFF_JOB_ID) JB FROM {P}PS_STAFF_INTERNAL_TRANSFERS WHERE CURRENT_JOB='Y' GROUP BY STAFF_ID) t ON t.STAFF_ID=c.STAFF_ID LEFT JOIN (SELECT USER_CODE, MAX(DESCRIPTION) DESCRIPTION FROM {P}CODES_MASTER WHERE CODE_TYPE=250 GROUP BY USER_CODE) j ON j.USER_CODE=t.JB WHERE c.STATUS='A' AND c.CURRENT_CONTRACT='Y') x GROUP BY (CASE WHEN x.ORG IN ('001','002','003','004') THEN '0'||SUBSTR(x.ORG,3,1) ELSE SUBSTR(NVL(x.ORG,'??'),1,2) END), NVL(x.JOB,'?'), NVL(TO_CHAR(x.NAT),'?') ORDER BY 1
